import re

def get_child_node(doc, scope, suffix):
    """Finds a child node of the scope with a title ending in suffix."""
    nodes = scope_nodes(doc, scope)
    for node in nodes:
        if node.get("title", "").endswith(suffix):
            return node
    return None

def parse_object_line(line):
    """Parses an object definition line."""
    # Format: "Object <id>: <description> (<attributes>)"
    m = re.match(r"Object (\d+): (.+?) \((.*)\)", line)
    if m:
        return m.group(1), m.group(2)
    return None, None

def parse_event_line(line):
    """Parses an event line."""
    # Format: "Frame <t>: <event text>"
    m_frame = re.match(r"Frame (\d+):", line)
    if not m_frame:
        return None
    frame = int(m_frame.group(1))
    rest = line[m_frame.end():].strip()

    # Extract object ID and action text
    # Format: "Object <id> <action text>"
    m_obj = re.match(r"Object (\d+) (.+)", rest)
    if not m_obj:
        return None

    obj_id = m_obj.group(1)
    text = m_obj.group(2)

    action = None
    other_id = None

    if "is in view when the video begins" in text:
        action = "start_view"
    elif "enters the scene" in text:
        action = "enter"
    elif "exits the scene" in text:
        action = "exit"
    elif "collides with Object" in text:
        action = "collide"
        m_other = re.search(r"collides with Object (\d+)", text)
        if m_other:
            other_id = m_other.group(1)

    return {
        "frame": frame,
        "obj_id": obj_id,
        "action": action,
        "other_id": other_id
    }

def get_motion_row(node, frame, obj_id):
    """Finds the motion log row for a specific object at a specific frame."""
    if not node:
        return None, None
    rows = table_rows(node)
    for idx, row_data in rows:
        r_frame_str = row_data.get("frame", "0")
        try:
            r_frame = int(r_frame_str)
        except ValueError:
            continue
        r_obj_str = row_data.get("object", "")
        # Object column format: "0 blue rubber cube"
        r_obj_id = r_obj_str.split()[0]
        if r_frame == frame and r_obj_id == obj_id:
            return idx, row_data
    return None, None

def entities(doc, scope):
    """Returns list of entities with IDs and descriptions."""
    node = get_child_node(doc, scope, "Objects")
    if not node:
        return []
    lines = node.get("lines", [])
    res = []
    for line in lines:
        obj_id, desc = parse_object_line(line)
        if obj_id is not None:
            res.append({"id": obj_id, "description": desc})
    return res

def recorded_end(doc, scope):
    """Returns the last time point (frame) covered by records."""
    node = get_child_node(doc, scope, "Motion log")
    if not node:
        return None
    rows = table_rows(node)
    max_frame = -1
    for idx, row_data in rows:
        try:
            f = int(row_data.get("frame", "0"))
        except ValueError:
            continue
        if f > max_frame:
            max_frame = f
    if max_frame == -1:
        return None
    return float(max_frame)

def inputs(doc, scope):
    """Returns inputs: entity entries and their initial states."""
    events_node = get_child_node(doc, scope, "Events")
    motion_node = get_child_node(doc, scope, "Motion log")
    if not events_node:
        return []

    lines = events_node.get("lines", [])
    res = []

    for line_idx, line in enumerate(lines):
        evt = parse_event_line(line)
        if not evt:
            continue

        # Inputs correspond to objects entering or being present at start
        if evt["action"] in ["start_view", "enter"]:
            obj_id = evt["obj_id"]
            frame = evt["frame"]

            # Find corresponding state in motion log
            row_idx, row_data = get_motion_row(motion_node, frame, obj_id)

            fields = {}
            if row_data:
                fields = {
                    "x": float(row_data.get("x", "0")),
                    "y": float(row_data.get("y", "0")),
                    "vx": float(row_data.get("vx", "0")),
                    "vy": float(row_data.get("vy", "0")),
                    "speed": float(row_data.get("speed", "0"))
                }

            # Source locations: Event line (time, entity) and Motion log row (state)
            src = [[events_node["node_id"], line_idx]]
            if row_data:
                src.append([motion_node["node_id"], row_idx, ["frame", "object", "x", "y", "vx", "vy", "speed"]])

            res.append({
                "id": f"entry_{obj_id}_{frame}",
                "time": float(frame),
                "kind": "entry",
                "entities": [obj_id],
                "fields": fields,
                "src": src
            })
    return res

def outcomes(doc, scope):
    """Returns outcomes: collisions and exits."""
    events_node = get_child_node(doc, scope, "Events")
    if not events_node:
        return []

    lines = events_node.get("lines", [])
    res = []

    for line_idx, line in enumerate(lines):
        evt = parse_event_line(line)
        if not evt:
            continue

        if evt["action"] == "collide":
            res.append({
                "time": float(evt["frame"]),
                "kind": "collision",
                "entities": [evt["obj_id"], evt["other_id"]],
                "value": None,
                "src": [[events_node["node_id"], line_idx]]
            })
        elif evt["action"] == "exit":
            res.append({
                "time": float(evt["frame"]),
                "kind": "exit",
                "entities": [evt["obj_id"]],
                "value": None,
                "src": [[events_node["node_id"], line_idx]]
            })
    return res

def params(doc, scope):
    """Returns constants stated in the document."""
    return {"stationary_threshold": 0.1}


# ---- step 2: forward model ----
import math
from collections import defaultdict

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    stationary_threshold = params.get("stationary_threshold", 0.1)

    # Determine horizon
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = 127.0

    sim_start = int(start) if start is not None else 0
    sim_horizon = int(horizon)

    # Get object info
    objects_node = get_child_node(doc, scope, "Objects")
    obj_info = {}
    if objects_node:
        for line in objects_node.get("lines", []):
            obj_id, desc = parse_object_line(line)
            if obj_id:
                parts = desc.split()
                material = parts[1] if len(parts) >= 2 else "rubber"
                shape = parts[2] if len(parts) >= 3 else "sphere"
                obj_info[obj_id] = {"material": material, "shape": shape}

    # Physics constants
    DT_POS = 0.028
    FRICTION_RUBBER = 0.005
    FRICTION_METAL = 0.003
    E = 0.2
    COLLISION_DIST = 0.42
    BOUNDARY_X = 2.6
    BOUNDARY_Y = 3.0

    def get_friction(obj_id):
        info = obj_info.get(obj_id, {})
        mat = info.get("material", "rubber")
        return FRICTION_RUBBER if mat == "rubber" else FRICTION_METAL

    def get_mass(obj_id):
        # Assume equal mass for simplicity
        return 1.0

    # Sort inputs by time
    sorted_inputs = sorted(inputs, key=lambda x: x["time"])

    # Collect which objects enter at which frames
    entry_map = defaultdict(list)
    for inp in sorted_inputs:
        frame = int(inp["time"])
        for eid in inp["entities"]:
            entry_map[frame].append(inp)

    # Initialize state at sim_start by propagating from entry times
    state = {}
    exited = set()

    for inp in sorted_inputs:
        entry_frame = int(inp["time"])
        if entry_frame <= sim_start:
            obj_id = inp["entities"][0]
            fields = inp.get("fields", {})
            x = fields.get("x", 0.0)
            y = fields.get("y", 0.0)
            vx = fields.get("vx", 0.0)
            vy = fields.get("vy", 0.0)

            # Propagate from entry_frame to sim_start
            f = get_friction(obj_id)
            for t in range(entry_frame, sim_start):
                speed = math.sqrt(vx**2 + vy**2)
                if speed > stationary_threshold:
                    x += vx * DT_POS
                    y += vy * DT_POS
                    vx *= (1 - f)
                    vy *= (1 - f)
                else:
                    vx = 0.0
                    vy = 0.0

            state[obj_id] = {"x": x, "y": y, "vx": vx, "vy": vy}

    # Track collision pairs to avoid duplicate detections within a few frames
    recent_collisions = {}  # pair -> last collision frame

    outcomes = []

    for frame in range(sim_start, sim_horizon + 1):
        # Add newly entering objects
        new_this_frame = False
        for inp in sorted_inputs:
            if int(inp["time"]) == frame:
                obj_id = inp["entities"][0]
                fields = inp.get("fields", {})
                state[obj_id] = {
                    "x": fields.get("x", 0.0),
                    "y": fields.get("y", 0.0),
                    "vx": fields.get("vx", 0.0),
                    "vy": fields.get("vy", 0.0)
                }
                new_this_frame = True

        # Update positions and apply friction for all active objects
        for obj_id in list(state.keys()):
            if obj_id in exited:
                continue
            s = state[obj_id]
            fric = get_friction(obj_id)
            speed = math.sqrt(s["vx"]**2 + s["vy"]**2)

            if speed > stationary_threshold:
                s["x"] += s["vx"] * DT_POS
                s["y"] += s["vy"] * DT_POS
                s["vx"] *= (1 - fric)
                s["vy"] *= (1 - fric)
            else:
                s["vx"] = 0.0
                s["vy"] = 0.0

        # Check for exits (only if moved beyond boundary)
        for obj_id in list(state.keys()):
            if obj_id in exited:
                continue
            s = state[obj_id]
            if abs(s["x"]) > BOUNDARY_X or abs(s["y"]) > BOUNDARY_Y:
                exited.add(obj_id)
                outcomes.append({
                    "time": float(frame),
                    "kind": "exit",
                    "entities": [obj_id],
                    "value": None,
                    "src": []
                })

        # Check for collisions
        active = [o for o in state.keys() if o not in exited]
        for i in range(len(active)):
            for j in range(i + 1, len(active)):
                obj1 = active[i]
                obj2 = active[j]

                pair = tuple(sorted([obj1, obj2]))

                # Check if recently collided (within 2 frames)
                if pair in recent_collisions and frame - recent_collisions[pair] < 2:
                    continue

                dx = state[obj2]["x"] - state[obj1]["x"]
                dy = state[obj2]["y"] - state[obj1]["y"]
                dist = math.sqrt(dx**2 + dy**2)

                if dist < COLLISION_DIST and dist > 0.001:
                    # Check if approaching (relative velocity along normal is negative)
                    nx = dx / dist
                    ny = dy / dist

                    dvx = state[obj1]["vx"] - state[obj2]["vx"]
                    dvy = state[obj1]["vy"] - state[obj2]["vy"]

                    dvn = dvx * nx + dvy * ny

                    # Collision happens if approaching or very close
                    if dvn > -0.05:  # Allow slight separation velocity
                        m1 = get_mass(obj1)
                        m2 = get_mass(obj2)

                        # Only resolve if approaching
                        if dvn > 0:
                            impulse = (1 + E) * dvn / (1.0/m1 + 1.0/m2)

                            state[obj1]["vx"] -= impulse / m1 * nx
                            state[obj1]["vy"] -= impulse / m1 * ny
                            state[obj2]["vx"] += impulse / m2 * nx
                            state[obj2]["vy"] += impulse / m2 * ny

                        # Separate overlapping
                        if dist < COLLISION_DIST * 0.8:
                            overlap = COLLISION_DIST - dist
                            state[obj1]["x"] -= overlap * 0.5 * nx
                            state[obj1]["y"] -= overlap * 0.5 * ny
                            state[obj2]["x"] += overlap * 0.5 * nx
                            state[obj2]["y"] += overlap * 0.5 * ny

                        recent_collisions[pair] = frame

                        outcomes.append({
                            "time": float(frame),
                            "kind": "collision",
                            "entities": sorted([obj1, obj2]),
                            "value": None,
                            "src": []
                        })

    return outcomes

