import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    if horizon is None:
        horizon = recorded_end(doc, scope) or 127.0
    if start is None:
        start = 0.0

    # Map entry times to inputs
    entry_map = {}
    for inp in inputs:
        t = int(inp["time"])
        entry_map.setdefault(t, []).append(inp)

    # Determine materials from entity descriptions
    mat_map = {}
    for e in entities(doc, scope):
        mat_map[e["id"]] = "metal" if "metal" in e["description"] else "rubber"

    state = {}
    outcomes = []
    collided = set()

    # Run simulation from t=0 to horizon to correctly initialise state at start
    t = 0
    while t <= int(horizon):
        # Add newly entered objects
        if t in entry_map:
            for inp in entry_map[t]:
                for oid in inp["entities"]:
                    state[oid] = {
                        "x": inp["fields"]["x"],
                        "y": inp["fields"]["y"],
                        "vx": inp["fields"]["vx"],
                        "vy": inp["fields"]["vy"],
                        "mat": mat_map.get(oid, "rubber")
                    }

        # Update positions and apply friction
        for oid, s in state.items():
            s["x"] += s["vx"]
            s["y"] += s["vy"]
            sp = math.hypot(s["vx"], s["vy"])
            if sp > 0.1:
                # Friction estimated from recorded data: metal ~0.008/frame, rubber ~0.003/frame
                fric = 0.008 if s["mat"] == "metal" else 0.003
                s["vx"] -= s["vx"]/sp * fric
                s["vy"] -= s["vy"]/sp * fric
            else:
                s["vx"] = 0.0
                s["vy"] = 0.0

        # Check for collisions
        ids = list(state.keys())
        for i in range(len(ids)):
            for j in range(i+1, len(ids)):
                o1, o2 = ids[i], ids[j]
                key = tuple(sorted((o1, o2)))
                if key in collided:
                    continue

                s1, s2 = state[o1], state[o2]
                d = math.hypot(s2["x"]-s1["x"], s2["y"]-s1["y"])

                # Collision threshold calibrated from recorded collision distances
                if d < 0.45:
                    collided.add(key)
                    outcomes.append({
                        "time": float(t),
                        "kind": "collision",
                        "entities": [o1, o2],
                        "value": None,
                        "src": []
                    })

                    # Apply 1D elastic collision response along the line of centers
                    if d > 0:
                        nx, ny = (s2["x"]-s1["x"])/d, (s2["y"]-s1["y"])/d
                        v1n = s1["vx"]*nx + s1["vy"]*ny
                        v2n = s2["vx"]*nx + s2["vy"]*ny

                        # Mass estimated from material: metal heavier than rubber
                        m1 = 2.0 if s1["mat"] == "metal" else 1.0
                        m2 = 2.0 if s2["mat"] == "metal" else 1.0

                        v1n_new = (v1n*(m1-m2) + 2*m2*v2n) / (m1+m2)
                        v2n_new = (v2n*(m2-m1) + 2*m1*v1n) / (m1+m2)

                        s1["vx"] += (v1n_new - v1n) * nx
                        s1["vy"] += (v1n_new - v1n) * ny
                        s2["vx"] += (v2n_new - v2n) * nx
                        s2["vy"] += (v2n_new - v2n) * ny

        t += 1

    # Return only outcomes strictly after the requested start time
    return [o for o in outcomes if o["time"] > start]

