import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """Forward simulation model for CLEVRER physics videos."""

    # Determine material properties from entities in scope
    entity_list = entities(doc, scope)
    mat_map = {}
    for e in entity_list:
        mat_map[e["id"]] = "metal" if "metal" in e.get("description", "") else "rubber"

    # If no horizon given, use recorded end or default
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = 127.0
    if start is None:
        start = 0.0

    # Build initial state from inputs
    # inputs contains entry events with positions and velocities
    state = {}  # obj_id -> {x, y, vx, vy, mat}
    entry_times = {}  # frame -> list of inputs

    for inp in inputs:
        t = int(inp["time"])
        for oid in inp["entities"]:
            state[oid] = {
                "x": inp["fields"]["x"],
                "y": inp["fields"]["y"],
                "vx": inp["fields"]["vx"],
                "vy": inp["fields"]["vy"],
                "mat": mat_map.get(oid, "rubber"),
                "entered": t,
                "active": True
            }
            entry_times.setdefault(t, []).append(inp)

    # Sort states for iteration
    obj_ids = sorted(state.keys(), key=lambda x: int(x) if x.isdigit() else 0)

    outcomes = []
    collided_pairs = set()  # Track pairs that have already collided
    exited = set()

    # Simulation parameters estimated from data
    FRICTION_METAL = 0.008   # speed reduction per frame for metal
    FRICTION_RUBBER = 0.003  # speed reduction per frame for rubber
    COLLISION_DIST = 0.42    # distance threshold for collision
    EXIT_BOUND = 3.5         # boundary for exit detection

    # We need to simulate from time 0 (or earliest entry) to horizon
    # But we should also propagate state correctly from entries
    sim_start = min(int(state[oid]["entered"]) for oid in state) if state else 0
    sim_start = min(sim_start, int(start))

    # Run simulation step by step
    t = sim_start
    while t <= int(horizon) + 1:
        # Add newly entered objects at this frame
        if t in entry_times:
            for inp in entry_times[t]:
                for oid in inp["entities"]:
                    if oid not in state:
                        state[oid] = {
                            "x": inp["fields"]["x"],
                            "y": inp["fields"]["y"],
                            "vx": inp["fields"]["vx"],
                            "vy": inp["fields"]["vy"],
                            "mat": mat_map.get(oid, "rubber"),
                            "entered": t,
                            "active": True
                        }

        active_ids = [oid for oid in obj_ids if oid in state and state[oid].get("active", False)]

        # Update positions and velocities
        for oid in active_ids:
            s = state[oid]
            if not s.get("active", False):
                continue

            # Update position
            s["x"] += s["vx"]
            s["y"] += s["vy"]

            # Apply friction
            sp = math.hypot(s["vx"], s["vy"])
            fric = FRICTION_METAL if s["mat"] == "metal" else FRICTION_RUBBER
            if sp > 0.1:  # stationary threshold
                s["vx"] -= (s["vx"] / sp) * fric
                s["vy"] -= (s["vy"] / sp) * fric
            else:
                s["vx"] = 0.0
                s["vy"] = 0.0

        # Check for collisions between active objects
        new_collisions = []
        for i in range(len(active_ids)):
            for j in range(i + 1, len(active_ids)):
                o1, o2 = active_ids[i], active_ids[j]
                pair = tuple(sorted([o1, o2]))
                if pair in collided_pairs:
                    continue

                s1, s2 = state[o1], state[o2]
                dist = math.hypot(s2["x"] - s1["x"], s2["y"] - s1["y"])

                if dist < COLLISION_DIST:
                    collided_pairs.add(pair)
                    new_collisions.append((o1, o2, s1, s2, pair))
                    if t > start:
                        outcomes.append({
                            "time": float(t),
                            "kind": "collision",
                            "entities": [o1, o2],
                            "value": None,
                            "src": []
                        })

        # Apply collision responses
        for o1, o2, s1, s2, pair in new_collisions:
            d = math.hypot(s2["x"] - s1["x"], s2["y"] - s1["y"])
            if d > 0.001:
                nx = (s2["x"] - s1["x"]) / d
                ny = (s2["y"] - s1["y"]) / d

                # Normal components
                v1n = s1["vx"] * nx + s1["vy"] * ny
                v2n = s2["vx"] * nx + s2["vy"] * ny

                # Use mass based on material: metal ~2x rubber
                m1 = 2.0 if s1["mat"] == "metal" else 1.0
                m2 = 2.0 if s2["mat"] == "metal" else 1.0

                # Elastic collision formulas
                v1n_new = (v1n * (m1 - m2) + 2 * m2 * v2n) / (m1 + m2)
                v2n_new = (v2n * (m2 - m1) + 2 * m1 * v1n) / (m1 + m2)

                s1["vx"] += (v1n_new - v1n) * nx
                s1["vy"] += (v1n_new - v1n) * ny
                s2["vx"] += (v2n_new - v2n) * nx
                s2["vy"] += (v2n_new - v2n) * ny

        # Check for exits
        for oid in active_ids:
            s = state[oid]
            if oid in exited:
                continue
            if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                exited.add(oid)
                s["active"] = False
                if t > start:
                    outcomes.append({
                        "time": float(t),
                        "kind": "exit",
                        "entities": [oid],
                        "value": None,
                        "src": []
                    })

        t += 1

    return outcomes

