            factor = FRICTION_METAL if s["mat"] == "metal" else FRICTION_RUBBER

            # Position update with scaling factor
            s["x"] += s["vx"] * SCALE
            s["y"] += s["vy"] * SCALE

            # Apply friction
            s["vx"] *= factor
            s["vy"] *= factor

            # Stop if very slow
            speed = math.hypot(s["vx"], s["vy"])
            if speed < 0.1:
                s["vx"] = 0.0
                s["vy"] = 0.0

        # Check for collisions between active objects
        new_collisions = []
        for i in range(len(active)):
            for j in range(i + 1, len(active)):
                o1, o2 = active[i], active[j]
                pair = tuple(sorted([o1, o2]))
                if pair in collided_pairs:
                    continue
                s1, s2 = state[o1], state[o2]
                d = math.hypot(s2["x"] - s1["x"], s2["y"] - s1["y"])
                if d < COLLISION_DIST:
                    collided_pairs.add(pair)
                    new_collisions.append((o1, o2))
                    if t > start:
                        outcomes.append({
                            "time": float(t),
                            "kind": "collision",
                            "entities": [o1, o2],
                            "value": None,
                            "src": []
                        })

        # Apply collision response (elastic-like with COR)
        for o1, o2 in new_collisions:
            s1, s2 = state[o1], state[o2]
            d = math.hypot(s2["x"] - s1["x"], s2["y"] - s1["y"])
            if d > 0.001:
                nx = (s2["x"] - s1["x"]) / d
                ny = (s2["y"] - s1["y"]) / d

                # Normal components of velocity
                v1n = s1["vx"] * nx + s1["vy"] * ny
                v2n = s2["vx"] * nx + s2["vy"] * ny

                m1 = MASS
                m2 = MASS

                # Collision response with coefficient of restitution
                v1n_new = v1n + (1 + COR) * (m2 / (m1 + m2)) * (v2n - v1n)
                v2n_new = v2n + (1 + COR) * (m1 / (m1 + m2)) * (v1n - v2n)

                s1["vx"] += (v1n_new - v1n) * nx
                s1["vy"] += (v1n_new - v1n) * ny
                s2["vx"] += (v2n_new - v2n) * nx
                s2["vy"] += (v2n_new - v2n) * ny

        # Check for exits
        for oid in active:
            s = state[oid]
            if oid in exited:
                continue
            if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                exited.add(oid)
                s["active"] = False
                if t > start:
                    outcomes.append({
                        "time": float(t),
                        "kind": "exit",
                        "entities": [oid],
                        "value": None,
                        "src": []
                    })

        t += 1

    return outcomes

