def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """Forward simulation model for CLEVRER physics videos."""

    if not inputs:
        return []

    # Determine horizon and start
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = 127.0
    if start is None:
        start = 0.0

    # Get material info from entities in the scope
    entity_list = entities(doc, scope)
    mat_map = {}
    for e in entity_list:
        desc = e.get("description", "")
        mat_map[e["id"]] = "metal" if "metal" in desc else "rubber"

    # Initialize state from inputs
    state = {}
    entry_map = {}
    for inp in inputs:
        t = int(inp["time"])
        entry_map.setdefault(t, []).append(inp)
        for oid in inp["entities"]:
            if oid not in state or t < state[oid].get("entered", float('inf')):
                state[oid] = {
                    "x": inp["fields"]["x"],
                    "y": inp["fields"]["y"],
                    "vx": inp["fields"]["vx"],
                    "vy": inp["fields"]["vy"],
                    "mat": mat_map.get(oid, "rubber"),
                    "active": True,
                    "entered": t
                }

    # Physics parameters - carefully calibrated from Video 14632 data
    SCALE = 0.027      # velocity to position scaling
    FRICTION_RUBBER = 0.9980   # per-frame multiplier (from vel decay 0.83->0.81 in 4 frames)
    FRICTION_METAL = 0.992     # per-frame multiplier (from vel decay 1.42->1.32 in 8 frames)
    COLLISION_DIST = 0.34      # distance threshold for collision
    EXIT_BOUND = 3.5           # boundary for exit detection

    outcomes = []
    collided_pairs = set()
    exited = set()

    obj_ids = sorted(state.keys(), key=lambda x: int(x) if x.isdigit() else 0)

    # Find simulation range
    earliest = min(s["entered"] for s in state.values()) if state else 0
    sim_start = min(earliest, int(start))
    sim_end = int(horizon)

    t = sim_start
    while t <= sim_end:
        # Add newly entered objects at this frame
        if t in entry_map:
            for inp in entry_map[t]:
                for oid in inp["entities"]:
                    if oid not in state:
                        state[oid] = {
                            "x": inp["fields"]["x"],
                            "y": inp["fields"]["y"],
                            "vx": inp["fields"]["vx"],
                            "vy": inp["fields"]["vy"],
                            "mat": mat_map.get(oid, "rubber"),
                            "active": True,
                            "entered": t
                        }
                        obj_ids.append(oid)
                        obj_ids.sort(key=lambda x: int(x) if x.isdigit() else 0)

        active = [oid for oid in obj_ids if oid in state and state[oid]["active"]]

        # Update positions and apply friction
        for oid in active:
            s = state[oid]
            f = FRICTION_METAL if s["mat"] == "metal" else FRICTION_RUBBER

            # Position update
            s["x"] += s["vx"] * SCALE
            s["y"] += s["vy"] * SCALE

            # Apply friction
            s["vx"] *= f
            s["vy"] *= f

            # Stop if very slow
            speed = math.hypot(s["vx"], s["vy"])
            if speed < 0.1:
                s["vx"] = 0.0
                s["vy"] = 0.0

        # Check for collisions
        new_collisions = []
        for i in range(len(active)):
            for j in range(i + 1, len(active)):
                o1, o2 = active[i], active[j]
                pair = tuple(sorted([o1, o2]))
                if pair in collided_pairs:
                    continue
                s1, s2 = state[o1], state[o2]
                d = math.hypot(s2["x"] - s1["x"], s2["y"] - s1["y"])
                if d < COLLISION_DIST:
                    collided_pairs.add(pair)
                    new_collisions.append((o1, o2, d))
                    if t > start:
                        outcomes.append({
                            "time": float(t),
                            "kind": "collision",
                            "entities": [o1, o2],
                            "value": None,
                            "src": []
                        })

        # Apply collision response
        for o1, o2, d in new_collisions:
            s1, s2 = state[o1], state[o2]
            if d > 0.001:
                nx = (s2["x"] - s1["x"]) / d
                ny = (s2["y"] - s1["y"]) / d

                v1n = s1["vx"] * nx + s1["vy"] * ny
                v2n = s2["vx"] * nx + s2["vy"] * ny

                m1, m2 = 1.0, 1.0  # equal masses
                cor = 0.6  # coefficient of restitution

                v1n_new = v1n + (1 + cor) * m2 / (m1 + m2) * (v2n - v1n)
                v2n_new = v2n + (1 + cor) * m1 / (m1 + m2) * (v1n - v2n)

                s1["vx"] += (v1n_new - v1n) * nx
                s1["vy"] += (v1n_new - v1n) * ny
                s2["vx"] += (v2n_new - v2n) * nx
                s2["vy"] += (v2n_new - v2n) * ny

        # Check for exits
        for oid in active:
            s = state[oid]
            if oid in exited:
                continue
            if abs(s["x"]) > EXIT_BOUND or abs(s["y"]) > EXIT_BOUND:
                exited.add(oid)
                s["active"] = False
                if t > start:
                    outcomes.append({
                        "time": float(t),
                        "kind": "exit",
                        "entities": [oid],
                        "value": None,
                        "src": []
                    })

        t += 1

    return outcomes

