import re

def get_child_node(doc, scope, suffix):
    """Finds a child node of the scope with a title ending in suffix."""
    nodes = scope_nodes(doc, scope)
    for node in nodes:
        if node.get("title", "").endswith(suffix):
            return node
    return None

def parse_object_line(line):
    """Parses an object definition line."""
    # Format: "Object <id>: <description> (<attributes>)"
    m = re.match(r"Object (\d+): (.+?) \((.*)\)", line)
    if m:
        return m.group(1), m.group(2)
    return None, None

def parse_event_line(line):
    """Parses an event line."""
    # Format: "Frame <t>: <event text>"
    m_frame = re.match(r"Frame (\d+):", line)
    if not m_frame:
        return None
    frame = int(m_frame.group(1))
    rest = line[m_frame.end():].strip()

    # Extract object ID and action text
    # Format: "Object <id> <action text>"
    m_obj = re.match(r"Object (\d+) (.+)", rest)
    if not m_obj:
        return None

    obj_id = m_obj.group(1)
    text = m_obj.group(2)

    action = None
    other_id = None

    if "is in view when the video begins" in text:
        action = "start_view"
    elif "enters the scene" in text:
        action = "enter"
    elif "exits the scene" in text:
        action = "exit"
    elif "collides with Object" in text:
        action = "collide"
        m_other = re.search(r"collides with Object (\d+)", text)
        if m_other:
            other_id = m_other.group(1)

    return {
        "frame": frame,
        "obj_id": obj_id,
        "action": action,
        "other_id": other_id
    }

def get_motion_row(node, frame, obj_id):
    """Finds the motion log row for a specific object at a specific frame."""
    if not node:
        return None, None
    rows = table_rows(node)
    for idx, row_data in rows:
        r_frame_str = row_data.get("frame", "0")
        try:
            r_frame = int(r_frame_str)
        except ValueError:
            continue
        r_obj_str = row_data.get("object", "")
        # Object column format: "0 blue rubber cube"
        r_obj_id = r_obj_str.split()[0]
        if r_frame == frame and r_obj_id == obj_id:
            return idx, row_data
    return None, None

def entities(doc, scope):
    """Returns list of entities with IDs and descriptions."""
    node = get_child_node(doc, scope, "Objects")
    if not node:
        return []
    lines = node.get("lines", [])
    res = []
    for line in lines:
        obj_id, desc = parse_object_line(line)
        if obj_id is not None:
            res.append({"id": obj_id, "description": desc})
    return res

def recorded_end(doc, scope):
    """Returns the last time point (frame) covered by records."""
    node = get_child_node(doc, scope, "Motion log")
    if not node:
        return None
    rows = table_rows(node)
    max_frame = -1
    for idx, row_data in rows:
        try:
            f = int(row_data.get("frame", "0"))
        except ValueError:
            continue
        if f > max_frame:
            max_frame = f
    if max_frame == -1:
        return None
    return float(max_frame)

