import math

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    stationary_threshold = params.get("stationary_threshold", 0.1)

    # Determine horizon
    if horizon is None:
        horizon = recorded_end(doc, scope)
        if horizon is None:
            horizon = 127.0

    # Get object info from the scope
    objects_node = get_child_node(doc, scope, "Objects")
    obj_info = {}
    if objects_node:
        for line in objects_node.get("lines", []):
            obj_id, desc = parse_object_line(line)
            if obj_id:
                parts = desc.split()
                material = parts[1] if len(parts) >= 2 else "rubber"
                shape = parts[2] if len(parts) >= 3 else "sphere"
                obj_info[obj_id] = {"material": material, "shape": shape}

    # Physics constants estimated from recorded data
    DT_POS = 0.028  # position displacement per velocity unit per frame
    FRICTION = {"rubber": 0.004, "metal": 0.003}  # multiplicative decay per frame
    E = 0.25  # coefficient of restitution (inelastic collisions)
    MASS = {"rubber": 1.0, "metal": 1.0}  # nearly equal masses
    COLLISION_DIST = 0.4  # collision distance threshold
    BOUNDARY = 2.5  # visible area boundary for exit detection

    def get_friction(obj_id):
        info = obj_info.get(obj_id, {})
        return FRICTION.get(info.get("material", "rubber"), 0.004)

    def get_mass(obj_id):
        info = obj_info.get(obj_id, {})
        return MASS.get(info.get("material", "rubber"), 1.0)

    # Sort inputs by time
    sorted_inputs = sorted(inputs, key=lambda x: x["time"])

    # State: obj_id -> {x, y, vx, vy}
    state = {}
    outcomes = []
    exited = set()

    sim_start = int(start) if start is not None else 0
    sim_horizon = int(horizon)

    # Initialize state at sim_start by propagating from entry times
    for inp in sorted_inputs:
        if inp["time"] < sim_start:
            obj_id = inp["entities"][0]
            fields = inp.get("fields", {})
            x = fields.get("x", 0)
            y = fields.get("y", 0)
            vx = fields.get("vx", 0)
            vy = fields.get("vy", 0)

            entry_time = int(inp["time"])
            for t in range(entry_time, sim_start):
                fric = get_friction(obj_id)
                speed = math.sqrt(vx**2 + vy**2)
                if speed > stationary_threshold:
                    x += vx * DT_POS
                    y += vy * DT_POS
                    vx *= (1 - fric)
                    vy *= (1 - fric)

            state[obj_id] = {"x": x, "y": y, "vx": vx, "vy": vy}

    # Track collision pairs to avoid duplicate detections
    recorded_collisions = set()

    # Simulate frame by frame
    for frame in range(sim_start, sim_horizon + 1):
        # Add newly entering objects
        new_objects = set()
        for inp in sorted_inputs:
            if int(inp["time"]) == frame:
                obj_id = inp["entities"][0]
                fields = inp.get("fields", {})
                state[obj_id] = {
                    "x": fields.get("x", 0),
                    "y": fields.get("y", 0),
                    "vx": fields.get("vx", 0),
                    "vy": fields.get("vy", 0)
                }
                new_objects.add(obj_id)

        # Update positions and apply friction
        for obj_id in list(state.keys()):
            if obj_id in exited:
                continue
            s = state[obj_id]
            fric = get_friction(obj_id)
            speed = math.sqrt(s["vx"]**2 + s["vy"]**2)

            if speed > stationary_threshold:
                # Don't move objects on their entry frame
                if obj_id not in new_objects:
                    s["x"] += s["vx"] * DT_POS
                    s["y"] += s["vy"] * DT_POS
                # Apply friction
                s["vx"] *= (1 - fric)
                s["vy"] *= (1 - fric)
            else:
                s["vx"] = 0.0
                s["vy"] = 0.0

        # Check for exits
        for obj_id in list(state.keys()):
            if obj_id in exited:
                continue
            s = state[obj_id]
            if abs(s["x"]) > BOUNDARY or abs(s["y"]) > BOUNDARY:
                exited.add(obj_id)
                outcomes.append({
                    "time": float(frame),
                    "kind": "exit",
                    "entities": [obj_id],
                    "value": None,
                    "src": []
                })

        # Check for collisions between all active object pairs
        active = [o for o in state.keys() if o not in exited]
        for i in range(len(active)):
            for j in range(i + 1, len(active)):
                obj1 = active[i]
                obj2 = active[j]

                pair = tuple(sorted([obj1, obj2]))
                if pair in recorded_collisions:
                    continue

                dx = state[obj2]["x"] - state[obj1]["x"]
                dy = state[obj2]["y"] - state[obj1]["y"]
                dist = math.sqrt(dx**2 + dy**2)

                if dist < COLLISION_DIST and dist > 0.001:
                    m1 = get_mass(obj1)
                    m2 = get_mass(obj2)

                    # Normal direction from obj1 to obj2
                    nx = dx / dist
                    ny = dy / dist

                    # Relative velocity
                    dvx = state[obj1]["vx"] - state[obj2]["vx"]
                    dvy = state[obj1]["vy"] - state[obj2]["vy"]

                    # Normal component of relative velocity
                    dvn = dvx * nx + dvy * ny

                    # Only collide if approaching
                    if dvn > 0:
                        # Impulse with coefficient of restitution
                        impulse = (1 + E) * dvn / (1.0/m1 + 1.0/m2)

                        # Update velocities
                        state[obj1]["vx"] -= impulse / m1 * nx
                        state[obj1]["vy"] -= impulse / m1 * ny
                        state[obj2]["vx"] += impulse / m2 * nx
                        state[obj2]["vy"] += impulse / m2 * ny

                        # Separate overlapping objects
                        overlap = COLLISION_DIST - dist
                        state[obj1]["x"] -= overlap * 0.5 * nx
                        state[obj1]["y"] -= overlap * 0.5 * ny
                        state[obj2]["x"] += overlap * 0.5 * nx
                        state[obj2]["y"] += overlap * 0.5 * ny

                        recorded_collisions.add(pair)

                        outcomes.append({
                            "time": float(frame),
                            "kind": "collision",
                            "entities": sorted([obj1, obj2]),
                            "value": None,
                            "src": []
                        })

    return outcomes

