    entry_map = defaultdict(list)
    for inp in sorted_inputs:
        frame = int(inp["time"])
        for eid in inp["entities"]:
            entry_map[frame].append(inp)

    # Initialize state at sim_start by propagating from entry times
    state = {}
    exited = set()

    for inp in sorted_inputs:
        entry_frame = int(inp["time"])
        if entry_frame <= sim_start:
            obj_id = inp["entities"][0]
            fields = inp.get("fields", {})
            x = fields.get("x", 0.0)
            y = fields.get("y", 0.0)
            vx = fields.get("vx", 0.0)
            vy = fields.get("vy", 0.0)

            # Propagate from entry_frame to sim_start
            f = get_friction(obj_id)
            for t in range(entry_frame, sim_start):
                speed = math.sqrt(vx**2 + vy**2)
                if speed > stationary_threshold:
                    x += vx * DT_POS
                    y += vy * DT_POS
                    vx *= (1 - f)
                    vy *= (1 - f)
                else:
                    vx = 0.0
                    vy = 0.0

            state[obj_id] = {"x": x, "y": y, "vx": vx, "vy": vy}

    # Track collision pairs to avoid duplicate detections within a few frames
    recent_collisions = {}  # pair -> last collision frame

    outcomes = []

    for frame in range(sim_start, sim_horizon + 1):
        # Add newly entering objects
        new_this_frame = False
        for inp in sorted_inputs:
            if int(inp["time"]) == frame:
                obj_id = inp["entities"][0]
                fields = inp.get("fields", {})
                state[obj_id] = {
                    "x": fields.get("x", 0.0),
                    "y": fields.get("y", 0.0),
                    "vx": fields.get("vx", 0.0),
                    "vy": fields.get("vy", 0.0)
                }
                new_this_frame = True

        # Update positions and apply friction for all active objects
        for obj_id in list(state.keys()):
            if obj_id in exited:
                continue
            s = state[obj_id]
            fric = get_friction(obj_id)
            speed = math.sqrt(s["vx"]**2 + s["vy"]**2)

            if speed > stationary_threshold:
                s["x"] += s["vx"] * DT_POS
                s["y"] += s["vy"] * DT_POS
                s["vx"] *= (1 - fric)
                s["vy"] *= (1 - fric)
            else:
                s["vx"] = 0.0
                s["vy"] = 0.0

        # Check for exits (only if moved beyond boundary)
        for obj_id in list(state.keys()):
            if obj_id in exited:
                continue
            s = state[obj_id]
            if abs(s["x"]) > BOUNDARY_X or abs(s["y"]) > BOUNDARY_Y:
                exited.add(obj_id)
                outcomes.append({
                    "time": float(frame),
                    "kind": "exit",
                    "entities": [obj_id],
                    "value": None,
                    "src": []
                })

        # Check for collisions
        active = [o for o in state.keys() if o not in exited]
        for i in range(len(active)):
            for j in range(i + 1, len(active)):
                obj1 = active[i]
                obj2 = active[j]

                pair = tuple(sorted([obj1, obj2]))

                # Check if recently collided (within 2 frames)
                if pair in recent_collisions and frame - recent_collisions[pair] < 2:
                    continue

                dx = state[obj2]["x"] - state[obj1]["x"]
                dy = state[obj2]["y"] - state[obj1]["y"]
                dist = math.sqrt(dx**2 + dy**2)

                if dist < COLLISION_DIST and dist > 0.001:
                    # Check if approaching (relative velocity along normal is negative)
                    nx = dx / dist
                    ny = dy / dist

                    dvx = state[obj1]["vx"] - state[obj2]["vx"]
                    dvy = state[obj1]["vy"] - state[obj2]["vy"]

                    dvn = dvx * nx + dvy * ny

                    # Collision happens if approaching or very close
                    if dvn > -0.05:  # Allow slight separation velocity
                        m1 = get_mass(obj1)
                        m2 = get_mass(obj2)

                        # Only resolve if approaching
                        if dvn > 0:
                            impulse = (1 + E) * dvn / (1.0/m1 + 1.0/m2)

                            state[obj1]["vx"] -= impulse / m1 * nx
                            state[obj1]["vy"] -= impulse / m1 * ny
                            state[obj2]["vx"] += impulse / m2 * nx
                            state[obj2]["vy"] += impulse / m2 * ny

                        # Separate overlapping
                        if dist < COLLISION_DIST * 0.8:
                            overlap = COLLISION_DIST - dist
                            state[obj1]["x"] -= overlap * 0.5 * nx
                            state[obj1]["y"] -= overlap * 0.5 * ny
                            state[obj2]["x"] += overlap * 0.5 * nx
                            state[obj2]["y"] += overlap * 0.5 * ny

                        recent_collisions[pair] = frame

                        outcomes.append({
                            "time": float(frame),
                            "kind": "collision",
                            "entities": sorted([obj1, obj2]),
                            "value": None,
                            "src": []
                        })

    return outcomes
